// store-shared — encrypted store shared between processes
// Backend: shm

fn ss_open::(name, password) {
    let shm = @shm_create(name, 65536);
    let salt = @crypto_random_bytes(16);
    let key = @crypto_pbkdf2(password, salt, 32, 32);
    let empty = @base64(@bytes(@json_encode({})));
    @shm_write(shm, 0, @bytes(@json_encode({"salt": @base64(salt), "data": empty})));
    return {"shm": shm, "key": key, "name": name};
}

fn ss_attach::(name, password) {
    let shm = @shm_open_z(name);
    let env = @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(shm, 0, 65536))));
    let salt = @base64_decode(env["salt"]);
    let key = @crypto_pbkdf2(password, salt, 32, 32);
    return {"shm": shm, "key": key, "name": name};
}

fn ss_decrypt::(store) {
    let env = @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(store["shm"], 0, 65536))));
    let cipher = @base64_decode(env["data"]);
    let mem = @mem_from_bytes(cipher);
    @mem_decrypt(mem, store["key"]);
    let plain = @mem_to_string(mem);
    @free(mem);
    return @json_decode(plain);
}

fn ss_save::(store, obj) {
    let plain = @bytes(@json_encode(obj));
    let mem = @mem_from_bytes(plain);
    @mem_encrypt(mem, store["key"]);
    let cipher = @base64(@mem_to_bytes(mem));
    @free(mem);
    let env = @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(store["shm"], 0, 65536))));
    env["data"] = cipher;
    @shm_write(store["shm"], 0, @bytes(@json_encode(env)));
    return true;
}

fn ss_get::(store, k) {
    let obj = ss_decrypt(store);
    if (@map_has_key(obj, k)) { return obj[k]; }
    return null;
}

fn ss_set::(store, k, v) {
    let obj = ss_decrypt(store);
    obj[k] = v;
    ss_save(store, obj);
    return v;
}

fn ss_del::(store, k) {
    let obj = ss_decrypt(store);
    let had = @map_has_key(obj, k);
    if (had) {
        obj = @map_omit_keys(obj, [k]);
        ss_save(store, obj);
    }
    return had;
}

fn version::() { return "1.0.0"; }
